import React, { useState, useEffect } from "react";
import Home from "./pages/Home";

export default function App() {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    if (dark) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [dark]);

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 p-8 transition">
      <div className="max-w-4xl mx-auto">

        {/* Header */}
        <div className="flex justify-between items-center mb-10">
          <div>
            <h1 className="text-4xl font-extrabold text-gray-800 dark:text-gray-100">
              Task Manager
            </h1>
            <p className="text-gray-500 dark:text-gray-400 text-sm">
              Organize. Prioritize. Execute.
            </p>
          </div>

          {/* Dark Mode Toggle */}
          <button
            onClick={() => setDark(!dark)}
            className="px-4 py-2 rounded-lg bg-gray-800 text-white dark:bg-gray-200 dark:text-black shadow"
          >
            {dark ? "Light Mode" : "Dark Mode"}
          </button>
        </div>

        {/* Main Card */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl p-6 border border-gray-200 dark:border-gray-700 transition">
          <Home />
        </div>
      </div>
    </div>
  );
}
